// Generated by analysis/scripts/env_target.py - do not edit by hand.
//
// The same 15 mixes, measured on the harmonic envelope (the vocal-tract curve
// with the harmonic ladder removed), averaged over the mixes, with the
// between-mix spread next to it.  Both come from aeq_cli's own ENVLINE output:
// a target built by the Python reference instead put one of the 15 mixes 4.6
// sigma off its own average, which cannot happen for a member of the sample
// (max sqrt(14) ~ 3.7) - the two implementations were measuring slightly
// different audio, and the difference was being charged to the song.
//
// Levels are re the 900-1150 Hz reference, the same convention as TargetCurve,
// but the two are NOT interchangeable: an envelope level sits ~14 dB below the
// raw level at 200 Hz and ~0.5 dB below at 1.5 kHz.
//
// Bands defined by fewer than 8 of the 15 takes carry kUndefined: this corpus
// sings between 197 and 350 Hz median, and a monophonic voice has no energy
// below its fundamental, so there is nothing to measure down there.
#pragma once
#include <array>
#include <cmath>
#include <algorithm>

namespace aeq {

struct EnvTargetCurve {
    static constexpr int    kPoints      = 86;
    static constexpr double kFmin        = 100.0;
    static constexpr double kPointsPerOct = 12.0;
    static constexpr float  kUndefined   = 999.0f;

    static const std::array<float, kPoints>& level() {
        static const std::array<float, kPoints> v {
       999.000f,   999.000f,   999.000f,   999.000f,   999.000f,   999.000f,
       999.000f,   999.000f,   999.000f,   999.000f,   999.000f,   999.000f,
       999.000f,   999.000f,   999.000f,   999.000f,     7.878f,     5.759f,
         4.358f,     3.480f,     2.506f,     2.149f,     2.061f,     2.597f,
         3.431f,     4.491f,     5.408f,     5.689f,     5.368f,     4.304f,
         2.730f,     1.169f,     0.323f,     0.397f,     1.166f,     1.869f,
         1.726f,     0.739f,    -0.178f,    -0.114f,     0.616f,     0.618f,
        -0.731f,    -1.854f,    -1.250f,    -0.302f,    -0.718f,    -0.840f,
         0.552f,     0.980f,     0.470f,     0.699f,     0.404f,    -0.102f,
        -0.085f,     0.461f,    -0.781f,    -0.882f,    -1.343f,    -0.579f,
        -0.942f,    -1.779f,    -1.188f,    -0.235f,    -1.070f,    -3.127f,
        -4.520f,    -5.042f,    -4.655f,    -3.459f,    -2.146f,    -2.122f,
        -2.563f,    -3.749f,    -4.805f,    -4.387f,    -4.680f,    -5.962f,
        -6.314f,    -7.057f,    -7.609f,    -8.526f,    -9.749f,   -11.270f,
       -12.792f,   -15.219f,
        };
        return v;
    }

    static const std::array<float, kPoints>& sd() {
        static const std::array<float, kPoints> v {
       999.000f,   999.000f,   999.000f,   999.000f,   999.000f,   999.000f,
       999.000f,   999.000f,   999.000f,   999.000f,   999.000f,   999.000f,
       999.000f,   999.000f,   999.000f,   999.000f,     3.893f,     4.458f,
         4.405f,     3.983f,     3.573f,     3.137f,     2.772f,     2.145f,
         1.804f,     1.982f,     2.450f,     2.788f,     2.747f,     2.347f,
         1.868f,     1.694f,     1.723f,     1.612f,     1.479f,     1.629f,
         1.662f,     1.282f,     0.939f,     0.782f,     0.513f,     0.747f,
         0.834f,     0.863f,     0.933f,     1.519f,     1.732f,     1.734f,
         2.001f,     2.293f,     2.826f,     3.078f,     4.097f,     4.362f,
         4.136f,     3.898f,     3.708f,     4.337f,     5.078f,     5.116f,
         4.549f,     3.309f,     2.372f,     2.895f,     4.341f,     6.204f,
         7.306f,     6.971f,     5.933f,     4.731f,     3.227f,     2.741f,
         3.199f,     4.149f,     5.193f,     5.574f,     5.706f,     5.791f,
         6.071f,     6.714f,     6.522f,     5.846f,     5.424f,     5.189f,
         4.722f,     4.552f,
        };
        return v;
    }

    static bool definedAt(double f) {
        const int i = indexOf(f);
        return i >= 0 && level()[i] < kUndefined * 0.5f;
    }
    static int indexOf(double f) {
        const double x = std::log2(std::max(f, 1.0) / kFmin) * kPointsPerOct;
        const int i = static_cast<int>(std::lround(x));
        return (i >= 0 && i < kPoints) ? i : -1;
    }
    // linear in log2(f), same interpolation as TargetCurve::at; kUndefined outside
    // the measured range, so callers must check definedAt() first.
    static double at(double f) { return interp(level(), f); }
    static double sdAt(double f) { return interp(sd(), f); }
private:
    template <typename T>
    static double interp(const T& v, double f) {
        const double x = std::log2(std::max(f, 1.0) / kFmin) * kPointsPerOct;
        if (x <= 0.0) return v.front();
        if (x >= kPoints - 1) return v.back();
        const int i = static_cast<int>(x);
        const double t = x - i;
        return v[i] * (1.0 - t) + v[i + 1] * t;
    }
};

} // namespace aeq
